CREATE DATABASE IF NOT EXISTS `eka-fashion` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE `eka-fashion`;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,nama VARCHAR(100) NOT NULL,username VARCHAR(50) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('admin','kasir') NOT NULL DEFAULT 'kasir',status ENUM('aktif','nonaktif') NOT NULL DEFAULT 'aktif',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE kategori(id INT AUTO_INCREMENT PRIMARY KEY,nama VARCHAR(100) NOT NULL,deskripsi TEXT);
CREATE TABLE supplier(id INT AUTO_INCREMENT PRIMARY KEY,nama VARCHAR(100) NOT NULL,telepon VARCHAR(30),alamat TEXT);
CREATE TABLE pelanggan(id INT AUTO_INCREMENT PRIMARY KEY,nama VARCHAR(100) NOT NULL,telepon VARCHAR(30),alamat TEXT);
CREATE TABLE produk(id INT AUTO_INCREMENT PRIMARY KEY,kode VARCHAR(30) UNIQUE,nama VARCHAR(120) NOT NULL,gambar VARCHAR(255) NULL,kategori_id INT,supplier_id INT,harga DECIMAL(12,2) NOT NULL DEFAULT 0,stok INT NOT NULL DEFAULT 0,FOREIGN KEY(kategori_id) REFERENCES kategori(id) ON DELETE SET NULL,FOREIGN KEY(supplier_id) REFERENCES supplier(id) ON DELETE SET NULL);
CREATE TABLE transaksi(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,pelanggan_id INT NULL,payment_method ENUM('cash','qris','transfer') NOT NULL DEFAULT 'cash',total DECIMAL(12,2) NOT NULL,cash_received DECIMAL(12,2) NOT NULL DEFAULT 0,change_amount DECIMAL(12,2) NOT NULL DEFAULT 0,tanggal TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(pelanggan_id) REFERENCES pelanggan(id) ON DELETE SET NULL);
CREATE TABLE detail_transaksi(id INT AUTO_INCREMENT PRIMARY KEY,transaksi_id INT NOT NULL,produk_id INT NOT NULL,jumlah INT NOT NULL,harga DECIMAL(12,2) NOT NULL,subtotal DECIMAL(12,2) NOT NULL,FOREIGN KEY(transaksi_id) REFERENCES transaksi(id) ON DELETE CASCADE,FOREIGN KEY(produk_id) REFERENCES produk(id));
